/**
 * The remote execution-world row.
 *
 * Mounted only by a remote profile (generated by the client's provisioner), it
 * holds the process open, owns the channel and answers the official helper's
 * method set. It depends on nothing but the profile's own execution providers,
 * so the remote host needs no agent loop, no model client and no credentials.
 */
import type { Context } from '@deepseek-ai/cordis'
import Schema from '@deepseek-ai/schemastery'
import { RemoteExecutionServer } from './controller.ts'
import { RemoteSessionStore } from './session-store.ts'
import { randomUUID } from 'node:crypto'
import { mkdirSync, readFileSync, unlinkSync, writeFileSync } from 'node:fs'
import { dirname } from 'node:path'

/** Loader row name. */
export const name = 'remote-workspace-server'

/** The execution providers this row serves; its profile always mounts them. */
export const inject = ['fs', 'subprocess', 'sandbox', 'sessionPersistence']

/** Server configuration; the client writes these values into the profile patch. */
export interface Config {
  /** Workspace used when the client does not name one. */
  workspace?: string
  /** Client lease; loss of heartbeats releases every owned process. */
  leaseMs?: number
  /** Maximum prepared or running process handles. */
  maxProcesses?: number
  /** Exit the host process after a `close` request, which a dedicated server profile wants. */
  exitOnClose?: boolean
  /** Stable identity for this installed server instance. */
  serverId?: string
  installationId?: string
  version?: string
  /** File containing the stable identity for this installed server. */
  identityFile?: string
  /** Standalone workspace index; ignored when workspaceRegistry is present. */
  workspaceIndex?: string
  /** Discovery manifest for this stdio server instance. */
  statusFile?: string
}

/** Validated at load time; a bad remote profile fails loudly instead of half-serving. */
export const Config: Schema<Config> = Schema.object({
  workspace: Schema.string().description('Workspace reported to the client when it does not name one.'),
  leaseMs: Schema.number().default(30_000).description('Client lease in milliseconds, refreshed by heartbeat.'),
  maxProcesses: Schema.number().default(128).description('Maximum prepared or running process handles.'),
  exitOnClose: Schema.boolean().default(true).description('Exit the process after the client closes the channel.'),
  serverId: Schema.string().default('').description('Stable server identity; generated when empty.'),
  installationId: Schema.string().default('').description('Installation identity used for multi-instance discovery.'),
  version: Schema.string().default('0.1.0-alpha27').description('Remote server plugin version.'),
  identityFile: Schema.string().default('').description('Stable identity file for this installation.'),
  workspaceIndex: Schema.string().default('').description('Standalone workspace index file.'),
  statusFile: Schema.string().default('').description('Instance discovery manifest path.'),
})

function stableId(file: string, fallback: string): string {
  if (file === '') return fallback
  mkdirSync(dirname(file), { recursive: true })
  try {
    const current = readFileSync(file, 'utf8').trim()
    if (current !== '') return current
  } catch {}
  writeFileSync(file, `${fallback}\n`, { mode: 0o600 })
  return fallback
}

/** Start the server on this process's stdio. */
export function apply(ctx: Context, config: Config): void {
  const serverId = stableId(config.identityFile ?? '', (config.serverId ?? '') === '' ? randomUUID() : config.serverId as string)
  const installationId = (config.installationId ?? '') === '' ? randomUUID() : config.installationId as string
  const sessionStore = new RemoteSessionStore(
    ctx,
    serverId,
    installationId,
    config.workspaceIndex === '' ? undefined : config.workspaceIndex,
  )
  const statusFile = config.statusFile ?? ''
  if (statusFile !== '') {
    mkdirSync(dirname(statusFile), { recursive: true })
    writeFileSync(statusFile, JSON.stringify({
      serverId,
      installationId,
      version: config.version ?? '0.1.0-alpha27',
      protocol: 2,
      transport: 'stdio',
      pid: process.pid,
    }) + '\n', { mode: 0o600 })
  }
  const server = new RemoteExecutionServer({
    ctx,
    input: process.stdin,
    output: process.stdout,
    workspace: config.workspace ?? process.cwd(),
    leaseMs: config.leaseMs,
    maxProcesses: config.maxProcesses,
    sessionStore,
    serverId: sessionStore.serverId,
    installationId: sessionStore.installationId,
    version: config.version,
    ...(config.exitOnClose === false
      ? {}
      : {
          onClose: (): void => {
            // A dedicated server profile has no app of its own, so leave once
            // the close response is on the wire — `process.exit` discards
            // queued writes, and an unref'd timer cannot be waited on.
            const leave = (): void => { process.exit(0) }
            const fallback = setTimeout(leave, 1_000)
            fallback.unref()
            process.stdout.write('', () => {
              clearTimeout(fallback)
              leave()
            })
          },
        }),
  })
  process.stdin.on('error', () => {})
  ctx.effect(() => () => {
    void server.dispose()
    if (statusFile !== '') {
      try { unlinkSync(statusFile) } catch {}
    }
  })
}
